sys_variable_value.value:
// ATF-CP-UI-01: Customer Portal Dashboard UI
await sn_atf.navigate('/x_2056099_indust_0_customer_portal.do#dashboard');
var dashHeading = await screen.findByText('Dashboard', { exact: false }, { timeout: 15000 });
await waitFor(function() { expect(dashHeading).toBeVisible(); });
var brand = await screen.findByText('Industrial Supply Co.', { exact: false });
expect(brand).toBeVisible();
var kpiLabels = ['Total Orders', 'Active Orders', 'In Production'];
for (var i = 0; i < kpiLabels.length; i++) {
    var el = await screen.queryByText(kpiLabels[i]);
    if (el) { expect(el).toBeVisible(); }
}
var welcomeEl = await screen.queryByText(/Welcome,/i);
var notLinkedEl = await screen.queryByText('Customer Account Not Linked');
if (welcomeEl) {
    expect(welcomeEl).toBeVisible();
    var currentOrders = await screen.queryByText('Current Orders');
    if (currentOrders) expect(currentOrders).toBeVisible();
    var nextDelivery = await screen.queryByText('Next Delivery');
    if (nextDelivery) expect(nextDelivery).toBeVisible();
    var bestSelling = await screen.queryByText('Best Selling Products');
    if (bestSelling) expect(bestSelling).toBeVisible();
} else if (notLinkedEl) {
    expect(notLinkedEl).toBeVisible();
}
var navTabs = ['Dashboard', 'Catalog', 'My Orders', 'Delivery'];
for (var t = 0; t < navTabs.length; t++) {
    var tab = await screen.queryByText(navTabs[t]);
    if (tab) expect(tab).toBeVisible();
}
